CREATE TABLE IF NOT EXISTS support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, requester_id uuid NOT NULL, subject text NOT NULL, description text NOT NULL, priority text NOT NULL DEFAULT 'P3', status text NOT NULL DEFAULT 'open', assignee_id uuid, sla_due_at timestamptz, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());